//! Matrix groups over finite fields: gl(n, q), sl(n, q) and the group
//! generated by invertible matrices over gf(q) or zmod(m).
//!
//! A matrix group is a permutation group in disguise: each matrix permutes
//! the q^n vectors of F^n, and the permutation determines the matrix (its
//! columns are the images of the unit vectors). So every group command works
//! on it, and elements are shown as matrices again.

use crate::ffield::{self as ff, Elem, Ring};
use crate::fgroup::{Group, Perm};
use crate::fmat::{self, FM};
use num_bigint::BigInt;
use num_traits::{One, ToPrimitive, Zero};
use std::collections::HashMap;
use std::rc::Rc;

pub type R<T> = Result<T, String>;

/// most points (vectors) a matrix group may act on
const MAX_POINTS: u64 = 60_000;

#[derive(Debug)]
pub struct Action {
    pub ring: Rc<Ring>,
    pub n: usize,
    vecs: Vec<Vec<Elem>>,
    index: HashMap<Vec<Vec<BigInt>>, usize>,
}

fn key(v: &[Elem]) -> Vec<Vec<BigInt>> {
    v.iter().map(|x| x.v.clone()).collect()
}

impl Action {
    pub fn new(ring: &Rc<Ring>, n: usize) -> R<Action> {
        let q = ring.size();
        let pts = num_traits::pow(q.clone(), n);
        if pts > BigInt::from(MAX_POINTS) {
            return Err(format!(
                "matrix groups act on the {}^{} = {} vectors of the space, which stops at {}",
                q, n, pts, MAX_POINTS
            ));
        }
        let (qn, pts) = (q.to_u64().unwrap(), pts.to_u64().unwrap());
        let all: Vec<Elem> = (0..qn)
            .map(|t| ring.elem(fmat::digits(t, &ring.n, ring.k)))
            .collect();
        let mut vecs = vec![];
        let mut index = HashMap::new();
        for t in 0..pts {
            let mut u = t;
            let v: Vec<Elem> = (0..n)
                .map(|_| {
                    let x = all[(u % qn) as usize].clone();
                    u /= qn;
                    x
                })
                .collect();
            index.insert(key(&v), vecs.len());
            vecs.push(v);
        }
        Ok(Action {
            ring: ring.clone(),
            n,
            vecs,
            index,
        })
    }

    pub fn degree(&self) -> usize {
        self.vecs.len()
    }

    /// The permutation of the vectors made by an invertible matrix
    pub fn perm(&self, m: &FM) -> R<Perm> {
        if m.len() != self.n || m.iter().any(|r| r.len() != self.n) {
            return Err(format!(
                "the group's matrices are {}x{}",
                self.n, self.n
            ));
        }
        if !fmat::det(m, &self.ring)?.is_unit() {
            return Err(format!(
                "{} is not invertible over {}, so it is not in a matrix group",
                crate::print::show(&fmat::expr(m)),
                self.ring.name()
            ));
        }
        Ok(self
            .vecs
            .iter()
            .map(|v| {
                let w: Vec<Elem> = m
                    .iter()
                    .map(|row| {
                        row.iter()
                            .zip(v)
                            .fold(self.ring.int(BigInt::zero()), |acc, (a, b)| acc.add(&a.mul(b)))
                    })
                    .collect();
                self.index[&key(&w)] as u16
            })
            .collect())
    }

    /// The matrix of a permutation: column j is the image of the j-th unit vector
    pub fn matrix(&self, p: &Perm) -> FM {
        let zero = self.ring.int(BigInt::zero());
        let one = self.ring.int(BigInt::one());
        let mut m = vec![vec![zero.clone(); self.n]; self.n];
        for j in 0..self.n {
            let e: Vec<Elem> = (0..self.n)
                .map(|i| if i == j { one.clone() } else { zero.clone() })
                .collect();
            let img = &self.vecs[p[self.index[&key(&e)]] as usize];
            for i in 0..self.n {
                m[i][j] = img[i].clone();
            }
        }
        m
    }

    pub fn expr(&self, p: &Perm) -> crate::expr::Expr {
        fmat::expr(&self.matrix(p))
    }

    /// group(M1, M2, ...), the text that rebuilds the group from generators
    pub fn gens_name(&self, gens: &[Perm]) -> String {
        let id = crate::fgroup::identity(self.degree());
        let gs: Vec<&Perm> = gens.iter().filter(|g| **g != id).collect();
        let shown: Vec<String> = if gs.is_empty() {
            vec![crate::print::fmt_one_line(&self.expr(&id))]
        } else {
            gs.iter().map(|g| crate::print::fmt_one_line(&self.expr(g))).collect()
        };
        format!("group({})", shown.join(", "))
    }
}

fn transvections(r: &Rc<Ring>, n: usize) -> Vec<FM> {
    // E + c e_ij for c = 1, a, ..., a^(k-1): they generate sl(n, q)
    let mut cs = vec![r.int(BigInt::one())];
    if r.k > 1 {
        let a = r.a();
        for _ in 1..r.k {
            let next = cs.last().unwrap().mul(&a);
            cs.push(next);
        }
    }
    let mut out = vec![];
    for i in 0..n {
        for j in 0..n {
            if i == j {
                continue;
            }
            for c in &cs {
                let mut m = fmat::identity(r, n);
                m[i][j] = c.clone();
                out.push(m);
            }
        }
    }
    out
}

fn build(name: String, a: Action, mats: &[FM]) -> R<Group> {
    let gens = mats.iter().map(|m| a.perm(m)).collect::<R<Vec<_>>>()?;
    let mut g = Group::new(name, a.degree(), gens).map_err(|e| {
        e.replace("the group has more than", "the matrix group has more than")
    })?;
    g.mats = Some(Rc::new(a));
    Ok(g)
}

/// |GL(n, q)| = (q^n - 1)(q^n - q)...(q^n - q^(n-1))
pub fn gl_order(n: usize, q: &BigInt) -> BigInt {
    let qn = num_traits::pow(q.clone(), n);
    (0..n).fold(BigInt::one(), |acc, i| acc * (&qn - num_traits::pow(q.clone(), i)))
}

fn check_size(n: usize, q: &BigInt, sl: bool) -> R<()> {
    let mut o = gl_order(n, q);
    if sl {
        o /= q - 1u32;
    }
    if o > BigInt::from(crate::fgroup::MAX_ORDER) {
        return Err(format!(
            "{}({}, {}) has {} elements; groups are listed element by element, which stops at {}",
            if sl { "sl" } else { "gl" },
            n,
            q,
            o,
            crate::fgroup::MAX_ORDER
        ));
    }
    Ok(())
}

pub fn gl(n: usize, q: &BigInt) -> R<Group> {
    check_size(n, q, false)?;
    let r = ff::gf(q)?;
    let a = Action::new(&r, n)?;
    let mut mats = transvections(&r, n);
    // a diagonal matrix with a generator of the units in the corner
    let mut d = fmat::identity(&r, n);
    d[0][0] = r.generator()?;
    mats.push(d);
    build(format!("gl({}, {})", n, q), a, &mats)
}

pub fn sl(n: usize, q: &BigInt) -> R<Group> {
    check_size(n, q, true)?;
    let r = ff::gf(q)?;
    let a = Action::new(&r, n)?;
    build(format!("sl({}, {})", n, q), a, &transvections(&r, n))
}

/// The group generated by invertible matrices over one ring
pub fn generated(ms: &[crate::expr::Expr]) -> R<Group> {
    let mut ring = None;
    let mut fms = vec![];
    for m in ms {
        let crate::expr::Expr::Matrix(rows) = m else {
            return Err("group: give matrices over one ring, such as gf(3, [1, 1; 0, 1])".into());
        };
        let r = fmat::ring_of(rows)?.ok_or("group: the matrices need a ring, such as gf(3, [1, 1; 0, 1])")?;
        if ring.as_ref().is_some_and(|x: &Rc<Ring>| *x != r) {
            return Err("group: the matrices must be over the same ring".into());
        }
        fms.push(fmat::lift(rows, &r)?);
        ring = Some(r);
    }
    let r = ring.unwrap();
    let n = fms[0].len();
    let a = Action::new(&r, n)?;
    let gens = fms.iter().map(|m| a.perm(m)).collect::<R<Vec<_>>>()?;
    let name = a.gens_name(&gens);
    let mut g = Group::new(name, a.degree(), gens)?;
    g.mats = Some(Rc::new(a));
    Ok(g)
}

/// The order of an invertible matrix over a finite ring (smallest k > 0 with A^k = I)
pub fn order(m: &FM, r: &Rc<Ring>) -> R<BigInt> {
    if !fmat::det(m, r)?.is_unit() {
        return Err("order: the matrix is not invertible, so it has no order".into());
    }
    let n = m.len();
    let id = fmat::identity(r, n);
    let mut p = m.clone();
    let mut k = BigInt::one();
    while p != id {
        p = fmat::mul(&p, m, r)?;
        k += 1u32;
        if k > BigInt::from(10_000_000u64) {
            return Err("order: more than ten million".into());
        }
    }
    Ok(k)
}
